### Objective
Build an enterprise-grade CI/CD Pipeline Simulator & Quality Gate Audit Dashboard in Flutter. The application provides learners with a hands-on simulation of an enterprise mobile continuous integration pipeline: executing formatting checks, static analysis with fatal linter warnings, headless test execution, LCOV coverage calculation with generated code filtering, threshold gating, and simulated Fastlane distribution artifacts.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(const CICDAutomationMasterclassApp());
}

class CICDAutomationMasterclassApp extends StatelessWidget {
  const CICDAutomationMasterclassApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'CI/CD Automation & Quality Gates',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.blueGrey,
        useMaterial3: true,
      ),
      home: const CIPipelineDashboardScreen(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. PIPELINE DOMAIN MODELS
// ─────────────────────────────────────────────────────────────────────────────

enum StageStatus { idle, running, passed, failed }

class PipelineStage {
  final String title;
  final String command;
  StageStatus status;
  String? failureReason;

  PipelineStage({
    required this.title,
    required this.command,
    this.status = StageStatus.idle,
    this.failureReason,
  });
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. INTERACTIVE PIPELINE DASHBOARD & TEST RUNNER
// ─────────────────────────────────────────────────────────────────────────────

class CIPipelineDashboardScreen extends StatefulWidget {
  const CIPipelineDashboardScreen({super.key});

  @override
  State<CIPipelineDashboardScreen> createState() => _CIPipelineDashboardScreenState();
}

class _CIPipelineDashboardScreenState extends State<CIPipelineDashboardScreen> {
  // Failure Injection Flags
  bool _injectLintViolation = false;
  bool _injectCoverageDrop = false;
  bool _injectGoldenMismatch = false;

  bool _isPipelineRunning = false;
  final List<String> _consoleLogs = [];
  double _cleanCoveragePercent = 84.6;
  final double _coverageThreshold = 80.0;

  late final List<PipelineStage> _stages;

  @override
  void initState() {
    super.initState();
    _resetStages();
  }

  void _resetStages() {
    _stages = [
      PipelineStage(title: 'Code Formatting & Linter', command: 'flutter analyze --fatal-infos'),
      PipelineStage(title: 'Headless Unit & Widget Tests', command: 'flutter test --coverage'),
      PipelineStage(title: 'LCOV Clean Filter & Coverage Gate', command: 'lcov --remove *.g.dart (Threshold: >=80%)'),
      PipelineStage(title: 'Golden Visual Regression Audit', command: 'flutter test --tags=golden'),
      PipelineStage(title: 'Fastlane Match & Release Bundling', command: 'fastlane build_and_sign_release'),
    ];
  }

  void _log(String line) {
    setState(() => _consoleLogs.add(line));
  }

  Future<void> _executePipeline() async {
    setState(() {
      _isPipelineRunning = true;
      _consoleLogs.clear();
      _resetStages();
    });

    _log('🚀 [CI RUNNER] Provisioning ubuntu-latest runner container...');
    _log('📦 [CACHE] Restoring Pub cache & Gradle dependencies (Hit: 1.2s)');
    await Future.delayed(const Duration(milliseconds: 300));

    // STAGE 1: Static Analysis
    _stages[0].status = StageStatus.running;
    setState(() {});
    _log('▶️ Executing: dart format --set-exit-if-changed && flutter analyze --fatal-infos');
    await Future.delayed(const Duration(milliseconds: 400));

    if (_injectLintViolation) {
      _stages[0].status = StageStatus.failed;
      _stages[0].failureReason = 'Fatal info: unused_local_variable found at lib/core/auth.dart:42';
      _log('❌ [LINT ERROR] lib/core/auth.dart:42:11: info: The value of local variable "token" isn\'t used.');
      _log('💥 [PIPELINE ABORTED] Quality Gate 1 violated: 1 fatal issue encountered.');
      setState(() => _isPipelineRunning = false);
      return;
    } else {
      _stages[0].status = StageStatus.passed;
      _log('✅ Static Analysis Passed: 0 errors, 0 warnings, 0 fatal infos.');
      setState(() {});
    }

    // STAGE 2: Test Suite Execution
    _stages[1].status = StageStatus.running;
    setState(() {});
    _log('▶️ Executing: flutter test --coverage --test-randomize-ordering-seed=random');
    await Future.delayed(const Duration(milliseconds: 450));
    _stages[1].status = StageStatus.passed;
    _log('✅ 53 tests passed across 6 test isolates (Duration: 1.34s, 0 failures).');
    setState(() {});

    // STAGE 3: LCOV Filter & Threshold Assertion
    _stages[2].status = StageStatus.running;
    setState(() {});
    _log('▶️ Filtering generated code: lcov --remove coverage/lcov.info "**/*.g.dart"');
    await Future.delayed(const Duration(milliseconds: 350));

    final currentCoverage = _injectCoverageDrop ? 67.4 : 84.6;
    setState(() => _cleanCoveragePercent = currentCoverage);

    if (currentCoverage < _coverageThreshold) {
      _stages[2].status = StageStatus.failed;
      _stages[2].failureReason = 'Coverage $currentCoverage% is below required 80.0% threshold!';
      _log('❌ [GATE FAIL] Clean domain coverage is $currentCoverage%. Minimum required is 80.0%.');
      _log('💥 [PIPELINE ABORTED] Pull request cannot be merged with degrading test coverage.');
      setState(() => _isPipelineRunning = false);
      return;
    } else {
      _stages[2].status = StageStatus.passed;
      _log('✅ Quality Gate Passed: Clean domain coverage at $currentCoverage% (>= 80.0%).');
      setState(() {});
    }

    // STAGE 4: Golden Visual Regression
    _stages[3].status = StageStatus.running;
    setState(() {});
    _log('▶️ Running Linux Docker visual goldens: flutter test --tags=golden');
    await Future.delayed(const Duration(milliseconds: 400));

    if (_injectGoldenMismatch) {
      _stages[3].status = StageStatus.failed;
      _stages[3].failureReason = 'Visual regression: 2.8% pixel diff on checkout_screen_golden.png';
      _log('❌ [GOLDEN MISMATCH] Golden comparison failed for "checkout_screen_golden.png"');
      _log('   Generated diff PNG stored at: build/reports/goldens/checkout_diff.png');
      _log('💥 [PIPELINE ABORTED] Visual regression detected in UI presentation layer.');
      setState(() => _isPipelineRunning = false);
      return;
    } else {
      _stages[3].status = StageStatus.passed;
      _log('✅ Golden Audit Passed: 14 snapshots verified with 0.0% pixel delta.');
      setState(() {});
    }

    // STAGE 5: Fastlane Match & Packaging
    _stages[4].status = StageStatus.running;
    setState(() {});
    _log('▶️ Fastlane Match: Decrypting signing certificates from private vault...');
    await Future.delayed(const Duration(milliseconds: 400));
    _stages[4].status = StageStatus.passed;
    _log('✅ Release Bundle Generated: build/app/outputs/bundle/release/app-release.aab');
    _log('🎉 [SUCCESS] All 5 Quality Gates satisfied! PR approved for automated merge.');

    setState(() => _isPipelineRunning = false);
  }

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Enterprise CI/CD & Quality Gates'),
        centerTitle: true,
      ),
      body: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          // Coverage Metric Gauge Card
          _buildCoverageMetricCard(colorScheme),
          const SizedBox(height: 16),

          // Failure Injection Control Panel
          _buildFailureControlPanel(colorScheme),
          const SizedBox(height: 20),

          // Pipeline Stage Tracker
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              const Text('Continuous Integration Pipeline', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 15)),
              FilledButton.icon(
                onPressed: _isPipelineRunning ? null : _executePipeline,
                icon: _isPipelineRunning
                    ? const SizedBox(width: 16, height: 16, child: CircularProgressIndicator(strokeWidth: 2, color: Colors.white))
                    : const Icon(Icons.play_circle_fill_rounded),
                label: Text(_isPipelineRunning ? 'Running CI...' : 'Trigger CI Workflow'),
              ),
            ],
          ),
          const SizedBox(height: 12),
          ..._stages.map((s) => _buildStageTile(s, colorScheme)),
          const SizedBox(height: 20),

          // Terminal Log Output
          const Text('Runner Terminal Stream (ANSI / LCOV)', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13)),
          const SizedBox(height: 8),
          Container(
            height: 200,
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: const Color(0xFF0D1117),
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: Colors.white12),
            ),
            child: _consoleLogs.isEmpty
                ? const Center(
                    child: Text('Tap "Trigger CI Workflow" to execute the automated quality gate pipeline.', style: TextStyle(color: Colors.white38, fontSize: 11)),
                  )
                : ListView.builder(
                    itemCount: _consoleLogs.length,
                    itemBuilder: (context, i) => Padding(
                      padding: const EdgeInsets.symmetric(vertical: 2.0),
                      child: Text(_consoleLogs[i], style: const TextStyle(color: Color(0xFF58A6FF), fontSize: 11, fontFamily: 'monospace')),
                    ),
                  ),
          ),
        ],
      ),
    );
  }

  Widget _buildCoverageMetricCard(ColorScheme colorScheme) {
    final isAboveThreshold = _cleanCoveragePercent >= _coverageThreshold;

    return Card(
      elevation: 0,
      color: colorScheme.surfaceContainerHighest,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      child: Padding(
        padding: const EdgeInsets.all(18),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                const Text('Clean Domain Coverage Gate', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14)),
                Text(
                  '${_cleanCoveragePercent.toStringAsFixed(1)}% (Target: >=80%)',
                  style: TextStyle(
                    fontWeight: FontWeight.bold,
                    fontSize: 13,
                    color: isAboveThreshold ? Colors.green.shade700 : Colors.red.shade700,
                  ),
                ),
              ],
            ),
            const SizedBox(height: 10),
            ClipRRect(
              borderRadius: BorderRadius.circular(8),
              child: LinearProgressIndicator(
                value: _cleanCoveragePercent / 100.0,
                minHeight: 10,
                backgroundColor: Colors.black12,
                valueColor: AlwaysStoppedAnimation<Color>(isAboveThreshold ? Colors.green : Colors.red),
              ),
            ),
            const SizedBox(height: 8),
            Text(
              'Filters *.g.dart, *.freezed.dart, and UI previews to measure genuine domain & state logic.',
              style: TextStyle(fontSize: 11, color: colorScheme.onSurfaceVariant),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildFailureControlPanel(ColorScheme colorScheme) {
    return Card(
      elevation: 0,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(16),
        side: BorderSide(color: colorScheme.outlineVariant),
      ),
      child: Padding(
        padding: const EdgeInsets.all(14),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text('Failure Injection Playground (Simulate CI Blocks)', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13)),
            const SizedBox(height: 8),
            SwitchListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              title: const Text('Inject Fatal Lint Warning (--fatal-infos)', style: TextStyle(fontSize: 12)),
              value: _injectLintViolation,
              onChanged: _isPipelineRunning ? null : (v) => setState(() => _injectLintViolation = v),
            ),
            SwitchListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              title: const Text('Simulate Coverage Drop to 67.4% (< 80% Gate)', style: TextStyle(fontSize: 12)),
              value: _injectCoverageDrop,
              onChanged: _isPipelineRunning ? null : (v) => setState(() => _injectCoverageDrop = v),
            ),
            SwitchListTile(
              dense: true,
              contentPadding: EdgeInsets.zero,
              title: const Text('Inject Golden Visual Regression (2.8% Delta)', style: TextStyle(fontSize: 12)),
              value: _injectGoldenMismatch,
              onChanged: _isPipelineRunning ? null : (v) => setState(() => _injectGoldenMismatch = v),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildStageTile(PipelineStage stage, ColorScheme colorScheme) {
    Widget icon;
    Color textColor = colorScheme.onSurface;

    switch (stage.status) {
      case StageStatus.idle:
        icon = const Icon(Icons.radio_button_unchecked, color: Colors.grey, size: 20);
      case StageStatus.running:
        icon = const SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2));
        textColor = colorScheme.primary;
      case StageStatus.passed:
        icon = const Icon(Icons.check_circle_rounded, color: Colors.green, size: 22);
      case StageStatus.failed:
        icon = const Icon(Icons.cancel_rounded, color: Colors.red, size: 22);
        textColor = Colors.red;
    }

    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      child: ListTile(
        leading: icon,
        title: Text(stage.title, style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13, color: textColor)),
        subtitle: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children:
 [
            Text(stage.command, style: TextStyle(fontSize: 10, fontFamily: 'monospace', color: colorScheme.onSurfaceVariant)),
            if (stage.failureReason != null)
              Padding(
                padding: const EdgeInsets.only(top: 4.0),
                child: Text(stage.failureReason!, style: const TextStyle(fontSize: 10, color: Colors.red, fontWeight: FontWeight.bold)),
              ),
          ],
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Sequential Pipeline Gating (`_executePipeline`)**:
   Orchestrates the 5 industry-standard mobile CI stages in order of increasing computational cost, failing fast at the earliest stage if standards are violated.
2. **Clean Domain Coverage Assertion**:
   Calculates coverage after filtering out generated code (`*.g.dart`), asserting that domain logic satisfies the mandatory 80.0% threshold.
3. **Fatal Lint Verification (`--fatal-infos`)**:
   Demonstrates how treating linter informationals as fatal build-breakers prevents technical debt accumulation in large developer teams.
4. **Interactive Failure Injection**:
   Allows learners to toggle lint failures, coverage regressions, or visual golden mismatches to observe how CI quality gates protect production branches.
